create extension if not exists pgcrypto;
create table public.admins(user_id uuid primary key references auth.users(id) on delete cascade,created_at timestamptz not null default now());
create table public.profiles(id uuid primary key default gen_random_uuid(),name text not null default 'Sinar',role text not null default 'Independent Developer',location text default 'Indonesia',bio text,avatar_url text,email text,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.projects(id uuid primary key default gen_random_uuid(),title text not null,slug text not null unique,description text not null,long_description text,category text,thumbnail_url text,live_url text,github_url text,featured boolean not null default false,published boolean not null default false,display_order integer not null default 0,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.project_images(id uuid primary key default gen_random_uuid(),project_id uuid not null references public.projects(id) on delete cascade,image_url text not null,alt_text text,display_order integer not null default 0,created_at timestamptz not null default now());
create table public.project_technologies(id uuid primary key default gen_random_uuid(),project_id uuid not null references public.projects(id) on delete cascade,name text not null,unique(project_id,name));
create table public.skills(id uuid primary key default gen_random_uuid(),name text not null,category text not null default 'Development',display_order integer not null default 0,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.experiences(id uuid primary key default gen_random_uuid(),role text not null,company text not null,description text,start_date text not null,end_date text,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.education(id uuid primary key default gen_random_uuid(),institution text not null,degree text not null,field text,start_date text,end_date text,description text,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.social_links(id uuid primary key default gen_random_uuid(),platform text not null,url text not null,display_order integer not null default 0,created_at timestamptz not null default now());
create table public.messages(id uuid primary key default gen_random_uuid(),name text not null,email text not null,subject text,message text not null,is_read boolean not null default false,created_at timestamptz not null default now());
create or replace function public.is_admin() returns boolean language sql stable security definer set search_path=public as $$ select exists(select 1 from public.admins where user_id=auth.uid()); $$;
DO $$ DECLARE t text; BEGIN FOREACH t IN ARRAY ARRAY['admins','profiles','projects','project_images','project_technologies','skills','experiences','education','social_links','messages'] LOOP EXECUTE format('alter table public.%I enable row level security',t); END LOOP; END $$;
create policy "admin membership self read" on public.admins for select using(user_id=auth.uid());
create policy "public profile read" on public.profiles for select using(true);
create policy "admin profile manage" on public.profiles for all using(public.is_admin()) with check(public.is_admin());
create policy "published projects read" on public.projects for select using(published or public.is_admin());
create policy "admin projects manage" on public.projects for all using(public.is_admin()) with check(public.is_admin());
create policy "published project images read" on public.project_images for select using(exists(select 1 from public.projects p where p.id=project_id and p.published) or public.is_admin());
create policy "admin project images manage" on public.project_images for all using(public.is_admin()) with check(public.is_admin());
create policy "published technologies read" on public.project_technologies for select using(exists(select 1 from public.projects p where p.id=project_id and p.published) or public.is_admin());
create policy "admin technologies manage" on public.project_technologies for all using(public.is_admin()) with check(public.is_admin());
create policy "public skills read" on public.skills for select using(true);
create policy "admin skills manage" on public.skills for all using(public.is_admin()) with check(public.is_admin());
create policy "public experiences read" on public.experiences for select using(true);
create policy "admin experiences manage" on public.experiences for all using(public.is_admin()) with check(public.is_admin());
create policy "public education read" on public.education for select using(true);
create policy "admin education manage" on public.education for all using(public.is_admin()) with check(public.is_admin());
create policy "public social read" on public.social_links for select using(true);
create policy "admin social manage" on public.social_links for all using(public.is_admin()) with check(public.is_admin());
create policy "visitor message submit" on public.messages for insert with check(true);
create policy "admin messages manage" on public.messages for all using(public.is_admin()) with check(public.is_admin());
insert into storage.buckets(id,name,public) values('portfolio-media','portfolio-media',true) on conflict do nothing;
create policy "public media read" on storage.objects for select using(bucket_id='portfolio-media');
create policy "admin media upload" on storage.objects for insert with check(bucket_id='portfolio-media' and public.is_admin());
create policy "admin media update" on storage.objects for update using(bucket_id='portfolio-media' and public.is_admin()) with check(bucket_id='portfolio-media' and public.is_admin());
create policy "admin media delete" on storage.objects for delete using(bucket_id='portfolio-media' and public.is_admin());
